"use strict";(self.webpackChunkdev_knowledge_base=self.webpackChunkdev_knowledge_base||[]).push([[8969],{500:a=>{a.exports=JSON.parse('{"tag":{"label":"Horizontal-Vertical Analysis","permalink":"/en/docs/tags/horizontal-vertical-analysis","allTagsPath":"/en/docs/tags","count":9,"items":[{"id":"LookAround/japanese-beer-horizontal-vertical-analysis","title":"150 Years of Japanese Beer: The Epic Rivalry of Four Brewing Giants","description":"A horizontal-vertical analysis of Japan\'s beer industry across 150 years \u2014 from the Black Ships to Asahi\'s Super Dry revolution, Kirin\'s Ichiban Shibori counterattack, Sapporo\'s marginalization, the happoshu tax arbitrage, and the triple squeeze of aging demographics, 2026 tax unification, and chuhai substitution.","permalink":"/en/docs/LookAround/japanese-beer-horizontal-vertical-analysis"},{"id":"LookAround/chinese-baijiu-horizontal-vertical-analysis","title":"Chinese Baijiu: From a Jug of Moonshine to an $800 Billion Empire","description":"A horizontal-vertical analysis of Chinese Baijiu \u2014 the world\'s largest distilled spirit category \u2014 covering its millennium-old origins, six eras of industry leadership, the $800-billion market structure, the six-giant competitive landscape, and future scenarios amid declining volume and rising profit.","permalink":"/en/docs/LookAround/chinese-baijiu-horizontal-vertical-analysis"},{"id":"LookAround/conveyor-belt-sushi-horizontal-vertical-analysis","title":"Conveyor-Belt Sushi: From Belt Spectacle to On-Demand Fulfillment System","description":"A horizontal-vertical analysis of conveyor-belt sushi, covering its origins, chain expansion, digital shift, competitive landscape, and the positioning of Sushiro, Hama Sushi, Kura Sushi, and other major brands.","permalink":"/en/docs/LookAround/conveyor-belt-sushi-horizontal-vertical-analysis"},{"id":"LookAround/hermes-horizontal-vertical-analysis","title":"Herm\xe8s: The Luxury Machine That Turned Slowness into a Moat","description":"A horizontal-vertical analysis of Herm\xe8s, covering its historical evolution, craft and governance model, luxury industry landscape, LVMH and Formula 1 as a contrast case, and the brand\'s future risks and judgment.","permalink":"/en/docs/LookAround/hermes-horizontal-vertical-analysis"},{"id":"LookAround/nurburgring-horizontal-vertical-analysis","title":"N\xfcrburgring: The Green Hell with 73 Corners","description":"A horizontal-vertical analysis of the N\xfcrburgring circuit complex \u2014 from its 1920s origins as a regional employment project to its current status as the global unit of measurement for performance marketing, examining the Nordschleife\'s irreplaceability, dual-track structure, public participation mechanism, and future in the electrification era.","permalink":"/en/docs/LookAround/nurburgring-horizontal-vertical-analysis"},{"id":"LookAround/omega-horizontal-vertical-analysis","title":"OMEGA: A Precision Timing Game Beyond the Moon","description":"A systematic study of the Swiss watch brand OMEGA, examining its historical evolution, technical trajectory, cultural assets, current competitive landscape, and future direction through the horizontal-vertical analysis framework.","permalink":"/en/docs/LookAround/omega-horizontal-vertical-analysis"},{"id":"LookAround/quant-trading-horizontal-vertical-analysis","title":"Quantitative Trading: Seventy-Plus Years from Casino Math to the AI Arms Race","description":"A horizontal-vertical analysis of quantitative trading\'s seventy-year evolution \u2014 from Ed Thorp\'s casino experiments and Jim Simons\' Medallion Fund to the LTCM collapse, the Flash Crash, the AI arms race, and China\'s unique quant trajectory under tightening regulation.","permalink":"/en/docs/LookAround/quant-trading-horizontal-vertical-analysis"},{"id":"LookAround/spa-francorchamps-horizontal-vertical-analysis","title":"Spa-Francorchamps: The Sanctuary of Rain, Fog, Gradients, and Courage","description":"A horizontal-vertical analysis of Circuit de Spa-Francorchamps \u2014 from its 1920s origins as a speed experiment on three public roads to the modern F1 rotational era, examining the Raidillon\'s totemic significance, the triple pressure of safety/weather/environment, and the transformation into a year-round destination.","permalink":"/en/docs/LookAround/spa-francorchamps-horizontal-vertical-analysis"},{"id":"LookAround/yuandao-flathead-earbuds-horizontal-vertical-analysis","title":"Yuandao and Flathead Earbuds: How a Ten-Yuan Earphone Punctures HiFi\'s Pricing Illusion","description":"A horizontal-vertical analysis of Yuandao / VIDO / NICEHCK Yuandao, covering brand history, the evolution of flathead earbuds, low-cost cult products, the impact of TWS, and future positioning.","permalink":"/en/docs/LookAround/yuandao-flathead-earbuds-horizontal-vertical-analysis"}],"unlisted":false}}')}}]);